class DiagnosisProbe:
    def __init__(self, view, device):
        self.view, self.device = view, device

    def run_full_diagnosis(self, train_loader):
        saved_state = capture_modes_and_rng(self.view.model)
        metrics, definitions = {}, {}
        try:
            self.view.model.eval()
            for probe in declared_dependency_order:
                blockers = current_unsatisfied_dependencies(probe, metrics)
                if blockers:
                    result = unavailable_with_specific_reasons(blockers)
                else:
                    try:
                        result = probe.measure(self.view, train_loader)
                    except Exception as exc:
                        result = error_with_exception_type_and_message(exc)
                metrics[probe.name] = result
                definitions[probe.name] = probe.definition

            for fault, relevant_probe, fixture in declared_mutation_cases:
                if diagnostic_budget_exhausted():
                    metrics[fault] = unavailable('Declared diagnostic cap reached')
                    continue
                control = relevant_probe.run_on_unchanged_fixture(fixture)
                with disposable_fault_injection(fault, fixture) as mutant:
                    observed = relevant_probe.run_on_fixture(mutant)
                metrics[fault] = assess_control_acceptance_and_mutant_rejection(
                    control, observed, require_discriminating_fixture=True)
                definitions[fault] = declared_fault_and_expected_detection(fault)
            return {'metrics': metrics, 'metric_definitions': definitions}
        finally:
            remove_all_temporary_hooks()
            restore_modes_and_rng(self.view.model, saved_state)


def diagnosis_interpreter_prompt(raw_diagnosis):
    return render_prompt_with_measured_metrics_and_definitions(
        raw_diagnosis,
        distinguish_partial_completion=True,
        prohibit_unsupported_validation_or_user_trait_claims=True)

